    :param input_string: str
    :return: str
    """
def first_letter_lower(input_string: Any) -> object {
    return (input_string[:1].lower() + input_string[1:]);
}

"""
    Normalizes provided path to: /something/something/something
    :param path:    string    path to normalize
    :return:        string    normalized path
    """
def normalize_path(path: Any) -> object {
    while ((path[(len(path) - 1)] == ' ') or (path[(len(path) - 1)] == '/')) {
        path = path[:(len(path) - 1)];
    }
    return path;
}
